import SwiftUI
import WebKit
import IskraCore

#if os(macOS)
typealias CallViewRepresentable = NSViewRepresentable
#else
typealias CallViewRepresentable = UIViewRepresentable
#endif

/// The web view Element Call is drawn in, and the pipe between it and the SDK.
///
/// The only web view in the app, and it earns its place by not being a browser: it loads exactly
/// one address, generated by the SDK for this room and this call, and it talks to exactly one
/// thing. Everything else about it is closed down — see `grantsCapture`, which is the part worth
/// reading twice.
///
/// ## The bridge, and why direction has to be worked out
///
/// A Matrix widget talks to its host by posting messages to `window.parent`. Element Call is
/// loaded here as the *top-level* page, so `window.parent === window` and every message it sends
/// is delivered straight back to itself — and to us, since we are listening on the same window.
/// `window.parent` cannot be reassigned in WebKit, so the way to tell our traffic from the
/// widget's is the envelope itself.
///
/// The widget API stamps every message with `api`, which names the *direction of the original
/// request* rather than of this particular message, and a reply carries a `response` field. So a
/// message coming **from** the widget is either a `fromWidget` request or a `toWidget` reply, and
/// a message going **to** it is the other two. That is the whole filter, and without it the page
/// hears its own requests echoed back and answers them forever.
struct CallWebView: CallViewRepresentable {
    /// Where to load. Generated by the SDK — see `CallStore`.
    let url: URL

    /// Messages the page sent, on their way to the SDK.
    let onMessage: (String) -> Void

    /// Handed the web view once it exists, so the screen can push SDK messages into it.
    let onReady: (WKWebView) -> Void

    /// The name the injected script posts to. Ours, so that a page which knows the widget API
    /// still has to be told this one.
    private static let handlerName = "iskraWidget"

    func makeCoordinator() -> Coordinator {
        Coordinator(url: url, onMessage: onMessage)
    }

    #if os(macOS)
    func makeNSView(context: Context) -> WKWebView { makeWebView(context: context) }
    func updateNSView(_ webView: WKWebView, context: Context) {}
    static func dismantleNSView(_ webView: WKWebView, coordinator: Coordinator) {
        tearDown(webView)
    }
    #else
    func makeUIView(context: Context) -> WKWebView { makeWebView(context: context) }
    func updateUIView(_ webView: WKWebView, context: Context) {}
    static func dismantleUIView(_ webView: WKWebView, coordinator: Coordinator) {
        tearDown(webView)
    }
    #endif

    private func makeWebView(context: Context) -> WKWebView {
        let content = WKUserContentController()
        content.add(context.coordinator, name: Self.handlerName)
        content.addUserScript(WKUserScript(source: Self.bridge,
                                           injectionTime: .atDocumentStart,
                                           forMainFrameOnly: true))

        let configuration = WKWebViewConfiguration()
        configuration.userContentController = content
        // A call that waited for a tap before playing anybody's voice would be a call nobody
        // could hear. This is the one place in the app where autoplay is the correct answer.
        configuration.mediaTypesRequiringUserActionForPlayback = []
        #if !os(macOS)
        // Without this iOS hands video to the full-screen player, which would take the call out
        // of our own screen and its bar.
        configuration.allowsInlineMediaPlayback = true
        #endif

        let webView = WKWebView(frame: .zero, configuration: configuration)
        webView.uiDelegate = context.coordinator
        webView.navigationDelegate = context.coordinator
        #if os(macOS)
        webView.setValue(false, forKey: "drawsBackground")
        #else
        webView.isOpaque = false
        webView.backgroundColor = .clear
        webView.scrollView.isScrollEnabled = false
        #endif

        webView.load(URLRequest(url: url))
        onReady(webView)
        return webView
    }

    /// Unhooks the script handler when the screen goes.
    ///
    /// Not tidiness: `WKUserContentController` holds the handler **strongly**, so a coordinator
    /// left attached keeps the whole screen alive after the call has ended, and the next call
    /// finds two listeners where it expects one.
    private static func tearDown(_ webView: WKWebView) {
        webView.configuration.userContentController.removeScriptMessageHandler(forName: handlerName)
        webView.stopLoading()
    }

    /// Sends one SDK message into the page.
    ///
    /// `window.postMessage` rather than `evaluateJavaScript` calling into the widget directly:
    /// the widget is listening for a message event, and posting one is the protocol it speaks.
    static func deliver(_ json: String, to webView: WKWebView) {
        // The message is already JSON, and it is embedded as a *string* and parsed on the far
        // side rather than pasted in as an object literal. Serialising it inside a one-element
        // array is the cheap way to get a correctly escaped JavaScript string literal: without it
        // a single apostrophe in somebody's display name is a syntax error in the middle of the
        // bridge, and the call simply stops hearing the SDK.
        guard let wrapped = try? JSONSerialization.data(withJSONObject: [json]),
              let literal = String(data: wrapped, encoding: .utf8)
        else {
            return
        }
        webView.evaluateJavaScript("window.postMessage(JSON.parse(\(literal)[0]), '*');")
    }

    private static let bridge = """
    (function () {
        window.addEventListener('message', function (event) {
            var data = event.data;
            if (!data || typeof data !== 'object') { return; }
            var isReply = Object.prototype.hasOwnProperty.call(data, 'response');
            var fromWidget = (data.api === 'fromWidget' && !isReply)
                          || (data.api === 'toWidget' && isReply);
            if (!fromWidget) { return; }
            window.webkit.messageHandlers.\(handlerName).postMessage(JSON.stringify(data));
        });
    })();
    """

    final class Coordinator: NSObject, WKScriptMessageHandler, WKUIDelegate, WKNavigationDelegate {
        private let url: URL
        private let onMessage: (String) -> Void

        init(url: URL, onMessage: @escaping (String) -> Void) {
            self.url = url
            self.onMessage = onMessage
        }

        func userContentController(_ controller: WKUserContentController,
                                   didReceive message: WKScriptMessage) {
            guard let json = message.body as? String else { return }
            onMessage(json)
        }

        /// Whether the page may open the microphone and the camera.
        ///
        /// The whole reason this is written out rather than left to the default: WebKit's default
        /// is to ask the person, with a prompt that names the *widget's* host and not the app, in
        /// the middle of a call they have already agreed to have. So it is answered here — and
        /// answered only for the deployment the call was generated against.
        ///
        /// A page that has navigated somewhere else and then asks for the microphone is refused,
        /// which is not a hypothetical worth skipping: this view has a network connection and an
        /// address bar it does not show.
        func webView(_ webView: WKWebView,
                     requestMediaCapturePermissionFor origin: WKSecurityOrigin,
                     initiatedByFrame frame: WKFrameInfo,
                     type: WKMediaCaptureType,
                     decisionHandler: @escaping (WKPermissionDecision) -> Void) {
            let sameHost = origin.host == url.host && origin.protocol.lowercased() == "https"
            decisionHandler(sameHost ? .grant : .deny)
        }

        /// The page may not leave the deployment it started on.
        ///
        /// Element Call's own navigation stays inside its host; anything that does not is either
        /// a link somebody managed to have the page open or a redirect somewhere unexpected, and
        /// in a view that holds a live Matrix widget driver neither is something to follow.
        func webView(_ webView: WKWebView,
                     decidePolicyFor navigationAction: WKNavigationAction,
                     decisionHandler: @escaping (WKNavigationActionPolicy) -> Void) {
            guard let target = navigationAction.request.url else {
                decisionHandler(.cancel)
                return
            }
            decisionHandler(target.host == url.host ? .allow : .cancel)
        }
    }
}
